private void createSumLine(AVAListZ5AType _type)
{
    AVAListZ5AData z5aLines;
    AVAListZ5AData z5aLineSum1;
    AVAListZ5AData z5aLineSum2;
    AVAListZ5AData z5aLineSum3;
    #define.EUR('EUR')
    ;
    ttsBegin;
    while select
        sum(PayablesDeposits),
        sum(PayablesMoreThanOneYear),
        sum(PayablesTillOneYear),
        sum(ReceivableDeposits),
        sum(ReceivableMoreThanOneYear),
        sum(ReceivableTillOneYear)
    from z5aLines
        group by z5aLines.CurrencyCode
        where z5aLines.Type         == _type
        &&    z5aLines.DispatchId   == listZ5ADispatchId
    {
        z5aLineSum1.DispatchId                  = listZ5ADispatchId;
        z5aLineSum1.Status                      = AVAListZ5AStatus::New;
        z5aLineSum1.Type                        = _type;
        z5aLineSum1.SeqNum                      = AVAListZ5AData::maxSeqNumDispatchType(listZ5ADispatchId, _type) + 1;
        z5aLineSum1.PosType                     = AVAListZ5APosType::Sum;
        z5aLineSum1.CountryRegionName           = "@SYS13865";
        z5aLineSum1.PayablesDeposits           += z5aLines.PayablesDeposits;
        z5aLineSum1.PayablesMoreThanOneYear    += z5aLines.PayablesMoreThanOneYear;
        z5aLineSum1.PayablesTillOneYear        += z5aLines.PayablesTillOneYear;
        z5aLineSum1.ReceivableDeposits         += z5aLines.ReceivableDeposits;
        z5aLineSum1.ReceivableMoreThanOneYear  += z5aLines.ReceivableMoreThanOneYear;
        z5aLineSum1.ReceivableTillOneYear      += z5aLines.ReceivableTillOneYear;

        if(z5aLines.CurrencyCode == #EUR)
        {
            z5aLineSum2.DispatchId                  = listZ5ADispatchId;
            z5aLineSum2.Status                      = AVAListZ5AStatus::New;
            z5aLineSum2.Type                        = _type;
            z5aLineSum2.SeqNum                      = AVAListZ5AData::maxSeqNumDispatchType(listZ5ADispatchId, _type) + 2;
            z5aLineSum2.PosType                     = AVAListZ5APosType::Sum;
            z5aLineSum2.CountryRegionName           = "@NDX:AVAZ5AInEUR";
            z5aLineSum2.CurrencyCode                = 'EUR';
            z5aLineSum2.PayablesDeposits           += z5aLines.PayablesDeposits;
            z5aLineSum2.PayablesMoreThanOneYear    += z5aLines.PayablesMoreThanOneYear;
            z5aLineSum2.PayablesTillOneYear        += z5aLines.PayablesTillOneYear;
            z5aLineSum2.ReceivableDeposits         += z5aLines.ReceivableDeposits;
            z5aLineSum2.ReceivableMoreThanOneYear  += z5aLines.ReceivableMoreThanOneYear;
            z5aLineSum2.ReceivableTillOneYear      += z5aLines.ReceivableTillOneYear;
        }

        if(z5aLines.CurrencyCode != #EUR)
        {
            z5aLineSum3.DispatchId                  = listZ5ADispatchId;
            z5aLineSum3.Status                      = AVAListZ5AStatus::New;
            z5aLineSum3.Type                        = _type;
            z5aLineSum3.SeqNum                      = AVAListZ5AData::maxSeqNumDispatchType(listZ5ADispatchId, _type) + 3;
            z5aLineSum3.PosType                     = AVAListZ5APosType::Sum;
            z5aLineSum3.CountryRegionName           = "@NDX:AVAZ5AOthCurrency";
            z5aLineSum3.PayablesDeposits           += z5aLines.PayablesDeposits;
            z5aLineSum3.PayablesMoreThanOneYear    += z5aLines.PayablesMoreThanOneYear;
            z5aLineSum3.PayablesTillOneYear        += z5aLines.PayablesTillOneYear;
            z5aLineSum3.ReceivableDeposits         += z5aLines.ReceivableDeposits;
            z5aLineSum3.ReceivableMoreThanOneYear  += z5aLines.ReceivableMoreThanOneYear;
            z5aLineSum3.ReceivableTillOneYear      += z5aLines.ReceivableTillOneYear;
        }
    }

    if( z5aLineSum1.PayablesDeposits           != 0
    ||  z5aLineSum1.PayablesMoreThanOneYear    != 0
    ||  z5aLineSum1.PayablesTillOneYear        != 0
    ||  z5aLineSum1.ReceivableDeposits         != 0
    ||  z5aLineSum1.ReceivableMoreThanOneYear  != 0
    ||  z5aLineSum1.ReceivableTillOneYear      != 0)
    {
        z5aLineSum1.TransDate=PerDate;
        z5aLineSum1.insert();
    }

    if( z5aLineSum2.PayablesDeposits           != 0
    ||  z5aLineSum2.PayablesMoreThanOneYear    != 0
    ||  z5aLineSum2.PayablesTillOneYear        != 0
    ||  z5aLineSum2.ReceivableDeposits         != 0
    ||  z5aLineSum2.ReceivableMoreThanOneYear  != 0
    ||  z5aLineSum2.ReceivableTillOneYear      != 0)
    {
        z5aLineSum2.TransDate=PerDate;
        z5aLineSum2.insert();
    }

    if( z5aLineSum3.PayablesDeposits           != 0
    ||  z5aLineSum3.PayablesMoreThanOneYear    != 0
    ||  z5aLineSum3.PayablesTillOneYear        != 0
    ||  z5aLineSum3.ReceivableDeposits         != 0
    ||  z5aLineSum3.ReceivableMoreThanOneYear  != 0
    ||  z5aLineSum3.ReceivableTillOneYear      != 0)
    {
        z5aLineSum3.TransDate=PerDate;
        z5aLineSum3.insert();
    }
    ttsCommit;
    z5aLineSum1.clear();
    z5aLineSum2.clear();
    z5aLineSum3.clear();
}

private void deleteOldValues()
{
    AVAListZ5AData listZ5AData;

    delete_from listZ5AData
        where listZ5AData.Status==AVAListZ5AStatus::New;
}

private void deleteZeroLines()
{
    AVAListZ5AData listZ5AData;

    ttsBegin;
    /*while select listZ5AData
        where listZ5AData.DispatchId                 == listZ5ADispatchId
        &&    listZ5AData.PosType                    == AVAListZ5APosType::Position
        &&    listZ5AData.PayablesDeposits           == 0
