        &&    listZ5AData.ReceivableMoreThanOneYear  == 0
        &&    listZ5AData.ReceivableTillOneYear      == 0
    {
        listZ5AData.delete();
    }*/
    delete_from listZ5AData where listZ5AData.DispatchId == listZ5ADispatchId
        &&    listZ5AData.PosType                    == AVAListZ5APosType::Position
        &&    listZ5AData.PayablesDeposits           == 0
        &&    listZ5AData.PayablesMoreThanOneYear    == 0
        &&    listZ5AData.PayablesTillOneYear        == 0
        &&    listZ5AData.ReceivableDeposits         == 0
        &&    listZ5AData.ReceivableMoreThanOneYear  == 0
        &&    listZ5AData.ReceivableTillOneYear      == 0;

    ttsCommit;
}

/// <summary>
/// AVAZ5A
